import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CWASMpdJ.js";const c=JSON.parse('{"title":"FAQ","description":"Answers to common Nette API questions - 404 for registered endpoints, 500 for valid responses, tokens, CORS, logging, OpenAPI and upgrading.","frontmatter":{"title":"FAQ","description":"Answers to common Nette API questions - 404 for registered endpoints, 500 for valid responses, tokens, CORS, logging, OpenAPI and upgrading."},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1793042989000}'),n={name:"faq.md"};function i(d,e,p,h,s,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="why-does-my-registered-endpoint-answer-404" tabindex="-1">Why does my registered endpoint answer 404? <a class="header-anchor" href="#why-does-my-registered-endpoint-answer-404" aria-label="Permalink to &quot;Why does my registered endpoint answer 404?&quot;">​</a></h2><p>The method, version, package and action of the request must match an <code>EndpointIdentifier</code> exactly, and the route must lead to <code>Api:Api:default</code>. See <a href="/nette-api/pr-preview/pr-184/guide/getting-started.html">Getting started</a>.</p><h2 id="my-handler-returns-the-right-data-but-the-client-gets-500-why" tabindex="-1">My handler returns the right data, but the client gets 500. Why? <a class="header-anchor" href="#my-handler-returns-the-right-data-but-the-client-gets-500-why" aria-label="Permalink to &quot;My handler returns the right data, but the client gets 500. Why?&quot;">​</a></h2><p>The response did not match any declared output, and output validation is on. Look at <code>detail</code>, or read <a href="/nette-api/pr-preview/pr-184/guide/outputs.html#when-outputs-are-validated">Outputs</a>.</p><h2 id="why-does-production-say-only-wrong-input" tabindex="-1">Why does production say only &quot;wrong input&quot;? <a class="header-anchor" href="#why-does-production-say-only-wrong-input" aria-label="Permalink to &quot;Why does production say only &quot;wrong input&quot;?&quot;">​</a></h2><p>Error details are off in production, also for <code>400</code>. See <a href="/nette-api/pr-preview/pr-184/guide/errors.html#error-details">Error handling</a>.</p><h2 id="how-do-i-protect-an-endpoint-with-a-token" tabindex="-1">How do I protect an endpoint with a token? <a class="header-anchor" href="#how-do-i-protect-an-endpoint-with-a-token" aria-label="Permalink to &quot;How do I protect an endpoint with a token?&quot;">​</a></h2><p>Use <code>BearerTokenAuthorization</code> or an API key class with a token repository. See <a href="/nette-api/pr-preview/pr-184/guide/authorization.html">Authorization</a>.</p><h2 id="why-does-my-browser-app-get-a-cors-error" tabindex="-1">Why does my browser app get a CORS error? <a class="header-anchor" href="#why-does-my-browser-app-get-a-cors-error" aria-label="Permalink to &quot;Why does my browser app get a CORS error?&quot;">​</a></h2><p>Set the allowed origin and enable preflight. See <a href="/nette-api/pr-preview/pr-184/guide/cors.html">CORS</a>.</p><h2 id="why-are-401-and-429-responses-not-in-my-log" tabindex="-1">Why are 401 and 429 responses not in my log? <a class="header-anchor" href="#why-are-401-and-429-responses-not-in-my-log" aria-label="Permalink to &quot;Why are 401 and 429 responses not in my log?&quot;">​</a></h2><p>The presenter returns before the logger in 3.x. See <a href="/nette-api/pr-preview/pr-184/guide/logging.html#what-is-logged">Logging</a>.</p><h2 id="how-do-i-publish-openapi" tabindex="-1">How do I publish OpenAPI? <a class="header-anchor" href="#how-do-i-publish-openapi" aria-label="Permalink to &quot;How do I publish OpenAPI?&quot;">​</a></h2><p>Register <code>OpenApiHandler</code> as an endpoint. See <a href="/nette-api/pr-preview/pr-184/guide/openapi.html">OpenAPI</a>.</p><h2 id="how-do-i-upgrade-from-2-x" tabindex="-1">How do I upgrade from 2.x? <a class="header-anchor" href="#how-do-i-upgrade-from-2-x" aria-label="Permalink to &quot;How do I upgrade from 2.x?&quot;">​</a></h2><p>Follow the <a href="/nette-api/pr-preview/pr-184/upgrade.html">upgrade guide</a> and the <a href="/nette-api/pr-preview/pr-184/changelog.html">changelog</a>.</p><h2 id="is-there-a-complete-project-i-can-run" tabindex="-1">Is there a complete project I can run? <a class="header-anchor" href="#is-there-a-complete-project-i-can-run" aria-label="Permalink to &quot;Is there a complete project I can run?&quot;">​</a></h2><p>Yes, 13 of them, tested in CI: see <a href="/nette-api/pr-preview/pr-184/examples/">Examples</a>.</p>',19)])])}const g=a(n,[["render",i]]);export{c as __pageData,g as default};
